/**
 * 转义字符串中的正则特殊字符，便于将字面量拼入 RegExp
 * @param {unknown} str 待转义字符串
 * @returns {string}
 */
export default function escapeRegExp(str) {
  return String(str).replace(/[\\^$.*+?()[\]{}|]/g, '\\$&');
}
